def generate(level=1, **kwargs):
    # Frozen sampled parameters defined directly as per task specification
    candidates = [11, 12, 13, 14]
    n = 156

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Find the prime candidate that divides n exactly
